# Generated by complete-me VERSION from: help.
_complete_me_rg() {
    local cur="${COMP_WORDS[COMP_CWORD]}" prev="${COMP_WORDS[COMP_CWORD-1]}"
    local path="" i w words files
    local -a tree=()
    for ((i = 1; i < COMP_CWORD; i++)); do
        w="${COMP_WORDS[i]}"
        [[ $w == -* ]] && continue
        local cand="${path:+$path }$w" t found=0
        for t in "${tree[@]}"; do [[ $t == "$cand" ]] && found=1 && break; done
        ((found)) && path="$cand" || break
    done
    case "$path|$prev" in
        '|--engine') COMPREPLY=($(compgen -W 'default pcre2 auto' -- "$cur")); return;;
        '|--type-add') COMPREPLY=($(compgen -W 'cpp py md' -- "$cur")); return;;
        '|--color') COMPREPLY=($(compgen -W 'never auto always ansi none' -- "$cur")); return;;
        '|--colors') COMPREPLY=($(compgen -W 'fg bg' -- "$cur")); return;;
        '|--hyperlink-format') COMPREPLY=($(compgen -W 'default none cursor file grep' -- "$cur")); return;;
    esac
    case "$path" in
        '') words='-e --regexp -f --file --pre --pre-glob -z --search-zip -s --case-sensitive --crlf --dfa-size-limit -E --encoding --engine -F --fixed-strings -i --ignore-case -v --invert-match -x --line-regexp -m --max-count --mmap -U --multiline --multiline-dotall --no-unicode --null-data -P --pcre2 --regex-size-limit -S --smart-case --stop-on-nonmatch -a --text -j --threads -w --word-regexp --auto-hybrid-regex --no-pcre2-unicode --binary -L --follow -g --glob --glob-case-insensitive --iglob --ignore-file --ignore-file-case-insensitive -d --max-depth --max-filesize --no-ignore --no-ignore-dot --no-ignore-exclude --no-ignore-files --no-ignore-global --no-ignore-parent --no-ignore-vcs --no-require-git --one-file-system -t --type -T --type-not --type-add --type-clear -u --unrestricted -A --after-context -B --before-context --block-buffered -b --byte-offset --color --colors --column -C --context --context-separator --field-context-separator --field-match-separator --heading -h --help --hostname-bin --hyperlink-format --include-zero --line-buffered -n --line-number -N --no-line-number -M --max-columns --max-columns-preview -0 --null -o --only-matching --path-separator --passthru -p --pretty -q --quiet -r --replace --sort --sortr --trim --vimgrep -H --with-filename -I --no-filename --sort-files -c --count --count-matches -l --files-with-matches --files-without-match --json --debug --no-ignore-messages --no-messages --stats --trace --files --generate --no-config --pcre2-version --type-list -V --version'; files=1;;
        *) words=""; files=1;;
    esac
    COMPREPLY=($(compgen -W "$words" -- "$cur"))
    if ((files)) && [[ $cur != -* ]]; then
        COMPREPLY+=($(compgen -f -- "$cur"))
    fi
}
complete -o bashdefault -o default -F _complete_me_rg rg
